select public.portco_profile_upsert($pp$[{"name":"The OpenAI Deployment Company","website":"https://openai.com/business/the-openai-deployment-company/","description":"A company designed to help organizations build and deploy AI systems they can rely on every day across their most important work, embedding Forward Deployed Engineers into customer organizations.","sector":"Technology","subsector":"AI deployment and transformation services","country":"United States","founded_year":2026,"business_model":"B2B","notes":"Launched 11 May 2026 as a majority-owned, OpenAI-controlled company with more than $4 billion of initial investment from 19 investment firms, consultancies and system integrators (led by TPG; Advent, Bain Capital and Brookfield co-lead founding partners). OpenAI agreed to acquire Tomoro (about 150 Forward Deployed Engineers and Deployment Specialists) for DeployCo. No dedicated chief executive is named on the sponsor or company pages read; leaders omitted.","sources":{"description":{"url":"https://www.adventinternational.com/news/openai-launches-the-openai-deployment-company-to-help-businesses-build-around-intelligence/","name":"Advent International","kind":"sponsor","as_of":"2026-05-11","evidence":"OpenAI is launching the OpenAI Deployment Company, a new company designed to help organizations build and deploy AI systems they can rely on every day across their most important work."},"website":{"url":"https://www.baincapitalprivateequity.com/portfolio","name":"Bain Capital Private Equity","kind":"sponsor","as_of":null,"evidence":"Name: The OpenAI Deployment Company ... View company website (links to https://openai.com/business/the-openai-deployment-company/)"},"sector":{"url":"https://www.baincapitalprivateequity.com/portfolio","name":"Bain Capital Private Equity","kind":"sponsor","as_of":null,"evidence":"INDUSTRY: Technology | YEAR: 2026 | DeployCo is an AI deployment and transformation services company formed in partnership with OpenAI to help enterprises